-- New catalogue, preserving all historical IDs, orders, payments and occupied seats.
alter table public.experiencias
 add column if not exists itinerario text[] not null default '{}',
 add column if not exists no_incluye text[] not null default '{}',
 add column if not exists recomendaciones text not null default '',
 add column if not exists condiciones text not null default '',
 add column if not exists cantidad_fija integer not null default 0;
alter table public.experiencias drop constraint if exists experiencias_filtros_check;
alter table public.experiencias add constraint experiencias_filtros_check check (
 cardinality(filtros) between 1 and 7 and filtros <@ array['Con amigos','En pareja','Al aire libre','Interior','Día','Noche','Conocer gente']::text[] and array_position(filtros,null) is null);
alter table public.experiencias drop constraint if exists experiencias_imagen_check;
alter table public.experiencias add constraint experiencias_imagen_check check (imagen in ('juegos','cocina','pintura','picnic','trivia','sabores','ceramica','plan-fogon-junto-al-lago','plan-secretos-del-fuego','plan-bajo-las-auroras','plan-entre-copas-y-quesos','plan-senderos-compartidos','plan-disena-tu-tote','plan-pizza-entre-amigos','plan-pinceles-y-picada','plan-picnic-frente-al-mar','plan-picnic-bajo-las-estrellas','plan-una-pausa-al-sol','plan-pasta-y-aperol','plan-tu-propia-mini-torta','plan-noche-de-luces','plan-amanecer-en-globo','plan-tarde-a-bordo','plan-mesa-de-autor','plan-cocina-de-autor-hecha-por-vos','plan-cine-para-dos','plan-cine-bajo-los-arboles','plan-ceramica-con-tu-sello','plan-ceramica-y-vino','plan-a-caballo-entre-paisajes'));
alter table public.experiencias drop constraint if exists experiencias_extended_content_check;
alter table public.experiencias add constraint experiencias_extended_content_check check (
 cardinality(itinerario) <= 4 and array_position(itinerario,null) is null and
 cardinality(no_incluye) <= 12 and array_position(no_incluye,null) is null and
 char_length(recomendaciones) <= 1000 and char_length(condiciones) <= 1000 and
 cantidad_fija between 0 and 10 and (id <> 'plan-cine-para-dos' or cantidad_fija = 2));
grant insert(itinerario,no_incluye,recomendaciones,condiciones,cantidad_fija), update(itinerario,no_incluye,recomendaciones,condiciones,cantidad_fija) on public.experiencias to authenticated;
create or replace function private.validate_experience() returns trigger language plpgsql set search_path = '' as $$
begin
 if exists(select 1 from unnest(new.incluye || new.itinerario || new.no_incluye) x where char_length(btrim(x)) not between 1 and 200)
 or (select count(distinct x) from unnest(new.filtros) x) <> cardinality(new.filtros) then
  raise check_violation using message = 'Invalid experience arrays';
 end if;
 if TG_OP = 'UPDATE' and new.id <> old.id then raise check_violation using message = 'Immutable experience ID'; end if;
 return new;
end;
$$;
-- Private release marker prevents reapplying seed data over later admin edits.
create table if not exists private.catalog_releases (version text primary key);
revoke all on private.catalog_releases from public, anon, authenticated;
do $seed$
begin
 if exists(select 1 from private.catalog_releases where version='20261030') then return; end if;
 update public.experiencias set estado='borrador' where estado='publicado' and id not in ('plan-fogon-junto-al-lago','plan-secretos-del-fuego','plan-bajo-las-auroras','plan-entre-copas-y-quesos','plan-senderos-compartidos','plan-disena-tu-tote','plan-pizza-entre-amigos','plan-pinceles-y-picada','plan-picnic-frente-al-mar','plan-picnic-bajo-las-estrellas','plan-una-pausa-al-sol','plan-pasta-y-aperol','plan-tu-propia-mini-torta','plan-noche-de-luces','plan-amanecer-en-globo','plan-tarde-a-bordo','plan-mesa-de-autor','plan-cocina-de-autor-hecha-por-vos','plan-cine-para-dos','plan-cine-bajo-los-arboles','plan-ceramica-con-tu-sello','plan-ceramica-y-vino','plan-a-caballo-entre-paisajes');
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-fogon-junto-al-lago','Fogón junto al lago','Al aire libre','Una tarde junto al agua, fuego y sobremesa compartida.','El agua marca el ritmo de esta tarde imaginada junto a un lago de Bariloche. La propuesta comienza con una recepción sencilla y tiempo para acomodarse en el sector de descanso, conversar y mirar cómo cambia la luz. Después llega una mesa de parrilla compartida, con una alternativa vegetariana para que el encuentro no dependa de comer carne. La sobremesa reúne al grupo alrededor del fogón, sin apuro y con abrigo a mano. La carpa que aparece en la fotografía acompaña la ambientación: este plan termina esa misma jornada y no ofrece alojamiento. Es una experiencia ficticia de demostración; la zona orienta el relato, pero no identifica un establecimiento ni una fecha real.','Bariloche, Río Negro','5 h',85000,array['En pareja','Con amigos','Al aire libre','Día','Noche']::text[],'plan-fogon-junto-al-lago','Carpa y sillas junto a un fogón frente al lago.',array['Recepción','Menú de parrilla y opción vegetariana','Bebida sin alcohol','Sector de descanso']::text[],array['Alojamiento','Traslado']::text[],array['Llegada y recepción','Tarde junto al lago','Asado compartido','Sobremesa al fogón']::text[],'Llevá abrigo, calzado cerrado y una capa para la tarde. Informá restricciones alimentarias antes de participar.','El viento o la lluvia pueden requerir reprogramación. La carpa es ambientación: no se ofrece una noche de camping.',0,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-fogon-junto-al-lago',16,0) on conflict(experiencia_id) do nothing;
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-secretos-del-fuego','Secretos del fuego','Al aire libre','Descubrí la cocina al fuego con las manos en la preparación.','Entender el fuego también es aprender a esperar. En este taller imaginado en San Antonio de Areco, la preparación del almuerzo sirve como hilo conductor para conocer técnicas y participar de una cocina compartida. El encuentro comienza con una introducción a los materiales y las tareas, continúa con ingredientes que se preparan en equipo y termina alrededor de la mesa. No se trata de una competencia ni hace falta llegar sabiendo cocinar: la idea es observar, probar y colaborar siguiendo las indicaciones. Los utensilios y la degustación forman parte de la propuesta. Esta actividad es una demostración académica, sin cocinero, establecimiento o fecha reales asociados; el exterior queda sujeto al clima.','San Antonio de Areco, Buenos Aires','4 h',95000,array['En pareja','Con amigos','Al aire libre','Día']::text[],'plan-secretos-del-fuego','Persona cocinando sobre parrillas al aire libre.',array['Introducción a técnicas','Ingredientes y utensilios','Degustación','Bebida sin alcohol']::text[],array['Traslado','Bebidas adicionales']::text[],array['Bienvenida y técnicas','Preparación en equipo','Cocción al fuego','Almuerzo compartido']::text[],'Usá calzado cerrado y ropa cómoda. Informá alergias o preferencias alimentarias.','Actividad participativa alrededor del fuego; seguí las indicaciones de acompañamiento. Con clima adverso, se reprograma.',0,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-secretos-del-fuego',12,0) on conflict(experiencia_id) do nothing;
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-bajo-las-auroras','Bajo las auroras','Al aire libre','Una noche para mirar el cielo y buscar luces del norte.','Mirar el cielo del norte requiere paciencia y una buena cantidad de abrigo. Esta salida ficticia toma Tromsø como zona ilustrativa y propone una noche de observación compartida, con acompañamiento y traslado local desde un punto de encuentro. Durante la salida hay tiempo para familiarizarse con la oscuridad, buscar colores en el horizonte y hacer una pausa con una bebida caliente. El atractivo está en la búsqueda y en el paisaje nocturno, no en una promesa de avistamiento: las auroras dependen de condiciones naturales que no se pueden asegurar. La propuesta no incluye viaje internacional ni hospedaje. Como parte del TP, no corresponde a una excursión contratada ni a una fecha real.','Tromsø, Noruega','4 h',240000,array['En pareja','Con amigos','Al aire libre','Noche']::text[],'plan-bajo-las-auroras','Dos siluetas bajo un cielo iluminado por auroras verdes.',array['Acompañamiento','Traslado local desde punto de encuentro','Bebida caliente']::text[],array['Vuelos','Alojamiento']::text[],array['Encuentro y preparación','Traslado local','Observación del cielo','Regreso']::text[],'Llevá abrigo térmico, guantes y calzado adecuado al frío.','Las auroras no están garantizadas: dependen del cielo y la actividad natural. El clima puede requerir reprogramación.',0,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-bajo-las-auroras',8,0) on conflict(experiencia_id) do nothing;
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-entre-copas-y-quesos','Entre copas y quesos','Al aire libre / Interior','Un recorrido entre aromas, copas y bocados para compartir.','Una copa y un bocado pueden abrir muchas conversaciones. Esta propuesta ficticia situada en Luján de Cuyo combina un recorrido de bodega con una mesa donde explorar aromas y contrastes. Primero se presenta el espacio y luego se pasa a tres degustaciones acompañadas por quesos, con tiempo para intercambiar impresiones sin necesitar vocabulario especializado. Quienes prefieran no tomar alcohol tienen una alternativa para participar del mismo encuentro. El recorrido combina momentos interiores y exteriores, de modo que el clima puede cambiar su organización. No se nombra una bodega real ni se prometen etiquetas concretas: es una experiencia de demostración, pensada para practicar una reserva y no para comercializar una visita existente.','Luján de Cuyo, Mendoza','2 h 30 min',68000,array['En pareja','Con amigos','Al aire libre','Interior','Día']::text[],'plan-entre-copas-y-quesos','Tabla de quesos y copas en una mesa frente a un viñedo.',array['Visita de bodega','Tres degustaciones','Tabla de quesos','Alternativa sin alcohol']::text[],array['Traslado','Compras de botellas']::text[],array['Bienvenida','Recorrido de bodega','Degustaciones','Tabla compartida']::text[],'Informá alergias y restricciones alimentarias; el maridaje contiene lácteos.','Alcohol solo para mayores de 18 años; se puede participar sin beber alcohol. El tramo exterior se adapta o reprograma por clima.',0,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-entre-copas-y-quesos',16,0) on conflict(experiencia_id) do nothing;
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-senderos-compartidos','Senderos compartidos','Al aire libre','Caminá a otro ritmo, con pausas para mirar el paisaje.','Caminar en compañía permite descubrir detalles que a veces pasan inadvertidos. Este recorrido ficticio de dificultad moderada toma Bariloche como referencia e intercala tramos de caminata con pausas para observar el paisaje y recuperar el ritmo. La jornada incluye acompañamiento y una vianda para compartir un descanso, mientras cada participante lleva su propia agua, abrigo y calzado adecuado. La propuesta exige considerar la condición física personal y consultar la dificultad antes de participar; no promete un recorrido accesible para cualquier situación. La fotografía es ilustrativa y no permite identificar el sendero presentado. Se trata de una demostración sin ruta comercial ni fecha confirmadas, y las condiciones meteorológicas pueden requerir reprogramación.','Bariloche, Río Negro','5 h',55000,array['En pareja','Con amigos','Al aire libre','Día']::text[],'plan-senderos-compartidos','Dos caminantes en un sendero rodeado de montañas.',array['Acompañamiento','Vianda']::text[],array['Traslado','Equipo personal']::text[],array['Preparación del recorrido','Caminata moderada','Pausa panorámica y vianda','Regreso']::text[],'Llevá calzado de trekking, abrigo por capas y agua propia. Consultá la exigencia antes de participar.','Dificultad moderada; el recorrido se reprograma con clima adverso. La fotografía es ilustrativa y no identifica el destino.',0,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-senderos-compartidos',8,0) on conflict(experiencia_id) do nothing;
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-disena-tu-tote','Diseñá tu tote','Interior','Transformá una bolsa de algodón en una pieza propia.','Una bolsa de algodón se convierte en una superficie para probar ideas. Este taller ficticio en Palermo invita a elegir colores, hacer un boceto sencillo y explorar la pintura textil con herramientas compartidas. No hay un diseño obligatorio: podés trabajar con formas, palabras o pequeñas ilustraciones, a tu ritmo y con orientación durante el proceso. La merienda propone una pausa para mirar lo que está creando el resto y volver a la mesa con nuevas ideas. Al finalizar quedan indicaciones para cuidar la pintura y respetar el secado. La experiencia no requiere práctica artística previa y forma parte de una demo académica, sin taller comercial ni dirección exacta asociados.','Palermo, CABA','2 h',32000,array['En pareja','Con amigos','Interior','Día']::text[],'plan-disena-tu-tote','Bolsas de tela pintadas y materiales de un taller textil.',array['Tote de algodón','Pinturas y herramientas','Guía','Merienda']::text[],array['Traslado','Materiales extra']::text[],array['Ideas y bocetos','Prueba de técnicas','Pintura de la tote','Merienda y cierre']::text[],'Traé ropa que pueda mancharse. Informá restricciones alimentarias para la merienda.','No hace falta experiencia previa. Se realiza en interior; respetá los tiempos de secado indicados.',0,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-disena-tu-tote',12,0) on conflict(experiencia_id) do nothing;
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-pizza-entre-amigos','Pizza entre amigos','Interior','Amasá, combiná sabores y compartí pizzas recién hechas.','La noche empieza con harina sobre la mesa y termina con pizzas para compartir. En esta propuesta ficticia de Villa Crespo, el grupo participa en la preparación de la masa, combina ingredientes y acompaña la cocción antes de sentarse a comer. El taller busca que cada persona encuentre una tarea, incluso si nunca amasó, y que la cena sea el resultado de esa colaboración. Los materiales y una bebida sin alcohol están incluidos; las preferencias alimentarias se conversan antes porque se trabaja con ingredientes que pueden contener alérgenos. No hay una pizzería real detrás de la propuesta: es una experiencia de demostración sin fecha ni proveedor contratado, pensada para recorrer el flujo de reserva.','Villa Crespo, CABA','3 h',45000,array['En pareja','Con amigos','Interior','Noche']::text[],'plan-pizza-entre-amigos','Pizzas caseras y participantes alrededor de una mesa.',array['Ingredientes','Utensilios','Taller','Bebida sin alcohol']::text[],array['Traslado','Bebidas adicionales']::text[],array['Preparación de masa','Elección de ingredientes','Cocción','Mesa compartida']::text[],'Usá calzado cerrado y recogé el pelo. Informá alergias: se trabaja con harina y lácteos.','No se requiere experiencia de cocina. No se garantiza un espacio libre de alérgenos.',0,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-pizza-entre-amigos',12,0) on conflict(experiencia_id) do nothing;
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-pinceles-y-picada','Pinceles y picada','Interior','Pintura libre, una mesa compartida y tiempo para crear.','No hace falta tener una idea cerrada para empezar a pintar. Este encuentro ficticio en Chacarita propone una mesa con soportes, colores y materiales donde cada participante pueda explorar una imagen propia. La guía acompaña las decisiones sin imponer un resultado, y una picada compartida invita a hacer pausas entre pinceladas. El objetivo es disfrutar del proceso y de la conversación, tanto en pareja como con amigos, sin convertir la actividad en una evaluación artística. Cada persona se lleva su obra al terminar, teniendo en cuenta que algunas partes pueden seguir húmedas. La propuesta es académica: no identifica un espacio comercial real ni garantiza un menú particular para restricciones alimentarias.','Chacarita, CABA','2 h 30 min',42000,array['En pareja','Con amigos','Interior','Noche']::text[],'plan-pinceles-y-picada','Materiales de pintura y picada sobre una mesa iluminada.',array['Soporte y pinturas','Materiales y guía','Picada','Bebida sin alcohol']::text[],array['Traslado','Enmarcado']::text[],array['Elección de colores','Primeros trazos','Pintura y picada','Cierre y retiro de obra']::text[],'Usá ropa que pueda mancharse e informá restricciones alimentarias.','No requiere conocimientos de pintura. Cada participante se lleva su obra; protegela mientras termina de secar.',0,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-pinceles-y-picada',12,0) on conflict(experiencia_id) do nothing;
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-picnic-frente-al-mar','Picnic frente al mar','Al aire libre','Una manta, algo rico y el mar como compañía.','La arena, el sonido del agua y una manta organizan esta pausa ficticia frente al mar. El picnic toma Mar del Plata como zona ilustrativa y propone una tarde con montaje preparado, almohadones y una tabla para compartir. La fruta y las bebidas sin alcohol acompañan un encuentro que deja espacio para conversar, descansar y mirar el horizonte, sin sumar actividades obligatorias. Conviene llevar abrigo aunque el día parezca cálido, porque el viento puede cambiar la sensación de temperatura. No incluye actividades acuáticas ni traslado. Esta experiencia de demostración no corresponde a un balneario ni a una reserva real; el estado del tiempo determina si habría que reprogramar el encuentro.','Mar del Plata, Buenos Aires','2 h 30 min',39000,array['En pareja','Con amigos','Al aire libre','Día']::text[],'plan-picnic-frente-al-mar','Fruta, copas y bocados sobre una manta en la arena.',array['Montaje, manta y almohadones','Tabla para compartir','Fruta','Bebida sin alcohol']::text[],array['Traslado','Actividades acuáticas']::text[],array['Recepción del picnic','Mesa frente al mar','Tiempo de descanso','Cierre']::text[],'Llevá abrigo liviano y protección solar. Informá restricciones alimentarias.','El viento o la lluvia requieren reprogramación. No incluye acceso a actividades en el agua.',0,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-picnic-frente-al-mar',8,0) on conflict(experiencia_id) do nothing;
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-picnic-bajo-las-estrellas','Picnic bajo las estrellas','Al aire libre','Un jardín, luces cálidas y una noche para conversar.','Cuando baja la luz, un jardín puede convertirse en un lugar distinto para encontrarse. Este picnic ficticio en Tigre combina mantas, una picada y una ambientación cálida que acompaña la conversación sin llenar la noche de actividades. La llegada permite acomodarse y compartir los primeros bocados; después queda tiempo para una sobremesa tranquila y para disfrutar del aire libre. El nombre invita a mirar hacia arriba, pero no promete estrellas visibles ni un cielo despejado. El abrigo y el repelente ayudan a prepararse para la propuesta. Es una experiencia de demostración, sin jardín comercial ni fecha reales, y las condiciones de lluvia o viento pueden llevar a reprogramarla.','Tigre, Buenos Aires','2 h 30 min',44000,array['En pareja','Con amigos','Al aire libre','Noche']::text[],'plan-picnic-bajo-las-estrellas','Picnic con almohadones en un jardín nocturno.',array['Montaje','Mantas','Picada','Bebida sin alcohol']::text[],array['Traslado','Alojamiento']::text[],array['Llegada al jardín','Picada compartida','Sobremesa bajo las luces','Cierre']::text[],'Traé abrigo y repelente. Informá restricciones alimentarias.','No se promete cielo despejado. Con lluvia o viento fuerte, se reprograma.',0,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-picnic-bajo-las-estrellas',8,0) on conflict(experiencia_id) do nothing;
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-una-pausa-al-sol','Una pausa al sol','Al aire libre','Frená la rutina con una canasta y un rato al aire libre.','Hay planes que necesitan poco más que una canasta y tiempo libre. Esta pausa ficticia en un espacio verde de San Isidro reúne bocados dulces y salados, fruta y limonada sobre una manta. La idea es llegar, acomodarse y decidir el ritmo del encuentro sin una agenda cargada: conversar, leer un rato o simplemente mirar alrededor. La canasta forma parte del montaje y no hace falta llevar vajilla propia para la propuesta. Sí conviene considerar protección solar y comentar restricciones alimentarias antes de participar. Como experiencia académica, no representa una oferta en un parque concreto ni asegura buen tiempo; si el clima no acompaña, corresponde pensar una reprogramación.','San Isidro, Buenos Aires','2 h',29000,array['En pareja','Con amigos','Al aire libre','Día']::text[],'plan-una-pausa-al-sol','Canastas y comida sobre una manta junto a un espacio verde.',array['Canasta y manta','Bocados dulces y salados','Fruta','Limonada']::text[],array['Traslado','Actividades adicionales']::text[],array['Recepción de la canasta','Picnic en el verde','Tiempo libre','Cierre']::text[],'Llevá protección solar y ropa cómoda. Avisá alergias o preferencias alimentarias.','El picnic depende del clima; con condiciones adversas se reprograma. No se garantiza sol.',0,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-una-pausa-al-sol',8,0) on conflict(experiencia_id) do nothing;
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-pasta-y-aperol','Pasta y Aperol','Interior','De la masa a la mesa: una cena hecha entre todos.','Estirar una masa y verla transformarse en cena es el centro de este encuentro ficticio en Colegiales. El taller propone preparar pasta fresca en compañía, conocer el proceso de formado y participar de la cocción antes de pasar a la mesa. Un aperitivo acompaña el momento social, con una alternativa sin alcohol para quienes la elijan. No se espera experiencia culinaria previa: las tareas se presentan de manera gradual y con utensilios disponibles para trabajar. La harina, el huevo y otros ingredientes requieren avisar alergias de antemano. Esta es una propuesta de demostración sin cocina comercial ni fecha reales; el nombre describe el plan y no una colaboración con una marca.','Colegiales, CABA','3 h',58000,array['En pareja','Con amigos','Interior','Noche']::text[],'plan-pasta-y-aperol','Manos preparando pasta fresca junto a copas de aperitivo.',array['Ingredientes y utensilios','Guía','Cena de pasta fresca','Un aperitivo por persona y alternativa sin alcohol']::text[],array['Traslado','Bebidas extra']::text[],array['Preparación de masa','Formado de pasta','Cocción','Cena compartida']::text[],'Usá ropa cómoda y calzado cerrado. Informá alergias a harina, huevo o lácteos.','Alcohol solo para mayores de 18 años, con opción sin alcohol. No se requiere experiencia previa.',0,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-pasta-y-aperol',12,0) on conflict(experiencia_id) do nothing;
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-tu-propia-mini-torta','Tu propia mini torta','Interior','Elegí rellenos, decorá y llevate una pequeña creación.','Una torta pequeña ofrece mucho espacio para jugar con colores y texturas. En este taller ficticio de Belgrano se parte de un bizcochuelo ya preparado, para dedicar el encuentro al relleno, el armado y la decoración. Cada participante elige cómo terminar su pieza con las herramientas disponibles, mientras recibe orientación para organizar las capas y los detalles. El café o té acompaña una pausa antes de colocar la creación en su caja para llevar. No incluye la elaboración y el horneado del bizcochuelo, ni exige conocimientos de pastelería. La propuesta pertenece a una demo académica sin local real asociado; las restricciones alimentarias deben consultarse y no se presupone ausencia de alérgenos.','Belgrano, CABA','2 h 30 min',46000,array['En pareja','Con amigos','Interior','Día']::text[],'plan-tu-propia-mini-torta','Mini tortas y herramientas de decoración en una mesa.',array['Bizcochuelo preparado y rellenos','Herramientas y decoración','Caja para llevar','Café o té']::text[],array['Traslado','Horneado del bizcochuelo']::text[],array['Elección de relleno','Armado de capas','Decoración','Caja y merienda']::text[],'Informá alergias y transportá la torta con cuidado.','Se parte de un bizcochuelo preparado; no se hornea durante el taller. No requiere experiencia previa.',0,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-tu-propia-mini-torta',12,0) on conflict(experiencia_id) do nothing;
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-noche-de-luces','Noche de luces','Al aire libre','Un paseo nocturno entre luces y música suave.','La luz cambia la forma de recorrer un jardín por la noche. Esta propuesta ficticia en Pilar imagina una instalación controlada con distintos puntos de iluminación y música suave, para caminar despacio y detenerse donde aparezca un detalle interesante. Una bebida sin alcohol acompaña una pausa durante el recorrido, que no requiere seguir una actividad competitiva ni participar de un espectáculo. La imagen funciona solamente como inspiración visual: no se ofrecen globos con fuego ni liberaciones al cielo. Tampoco se afirma relación con un festival existente. Es una experiencia académica sin sede ni fecha reales, sujeta a reprogramación si la lluvia o el viento impiden disfrutar del espacio exterior.','Pilar, Buenos Aires','2 h',35000,array['En pareja','Con amigos','Al aire libre','Noche']::text[],'plan-noche-de-luces','Luces cálidas suspendidas en un cielo nocturno, imagen de inspiración.',array['Acceso','Instalación de luces','Bebida sin alcohol']::text[],array['Traslado','Actividades con fuego']::text[],array['Recepción','Recorrido lumínico','Pausa con música','Cierre']::text[],'Usá calzado cómodo y llevá abrigo.','Instalación controlada: no se liberan globos con fuego. La imagen es inspiración, no un festival real. Se reprograma por clima adverso.',0,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-noche-de-luces',20,0) on conflict(experiencia_id) do nothing;
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-amanecer-en-globo','Amanecer en globo','Al aire libre','Contemplá el amanecer desde una perspectiva distinta.','Ver cómo cambia la luz al amanecer es el hilo de esta experiencia ficticia en Capadocia. La propuesta reúne un traslado local, el tiempo de preparación y una actividad de vuelo aproximada de cuarenta y cinco a sesenta minutos, seguida por un desayuno. Las tres horas indicadas abarcan el conjunto del encuentro, no tres horas de vuelo. El clima puede modificar la organización o hacer necesaria una reprogramación, por lo que no se promete un despegue en cualquier condición. Cada participante debe consultar previamente las condiciones personales de participación. Este plan académico no identifica un operador real ni atribuye certificaciones, y no incluye vuelos internacionales, viaje al destino ni alojamiento.','Capadocia, Turquía','3 h en total',220000,array['En pareja','Con amigos','Al aire libre','Día']::text[],'plan-amanecer-en-globo','Globos aerostáticos sobre un paisaje rocoso al amanecer.',array['Traslado local','Preparación','Vuelo aproximado de 45–60 minutos','Desayuno']::text[],array['Vuelos internacionales','Alojamiento']::text[],array['Traslado y preparación','Indicaciones iniciales','Vuelo al amanecer','Desayuno']::text[],'Llevá abrigo y calzado cerrado. Consultá condiciones personales de participación antes de reservar.','Sujeto a condiciones meteorológicas y reprogramación. No se atribuyen certificaciones a operadores ficticios.',0,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-amanecer-en-globo',8,0) on conflict(experiencia_id) do nothing;
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-tarde-a-bordo','Tarde a bordo','Al aire libre','Navegación compartida, música y horizonte abierto.','El horizonte y el movimiento del agua marcan esta tarde ficticia frente a la costa de Mallorca. La propuesta es una salida compartida en velero, con tripulación, música y un aperitivo para acompañar la navegación. Después del embarque y las indicaciones iniciales, el tiempo se reparte entre observar el paisaje y conversar a bordo, sin prometer paradas o actividades acuáticas específicas. Las bebidas incluidas son sin alcohol y conviene avisar restricciones alimentarias antes de participar. La duración contempla también el regreso, mientras que el viaje hasta el destino queda por cuenta propia. Se trata de una demostración académica sin embarcación contratada ni fecha real, cuya realización dependería del estado del mar.','Costa de Mallorca, España','4 h',110000,array['En pareja','Con amigos','Al aire libre','Día']::text[],'plan-tarde-a-bordo','Vista desde arriba de un velero sobre agua turquesa.',array['Navegación en velero','Tripulación','Aperitivo','Bebidas sin alcohol']::text[],array['Traslados al destino','Alojamiento']::text[],array['Embarque e indicaciones','Navegación','Aperitivo a bordo','Regreso']::text[],'Llevá protección solar, abrigo liviano y calzado adecuado. Informá restricciones alimentarias.','Seguí las indicaciones a bordo. Las condiciones del mar pueden requerir reprogramación; no se prometen actividades acuáticas.',0,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-tarde-a-bordo',8,0) on conflict(experiencia_id) do nothing;
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-mesa-de-autor','Mesa de autor','Interior','Cinco pasos para descubrir sabores en una mesa compartida.','Una cena puede ser una sucesión de pequeñas sorpresas. Esta mesa ficticia en Recoleta propone un menú degustación de cinco pasos, con espacio entre platos para descubrir combinaciones y compartir impresiones. La experiencia empieza con una recepción, continúa con los primeros sabores y platos centrales, y termina con un cierre dulce. El agua y una bebida sin alcohol acompañan el recorrido sin exigir un maridaje alcohólico. Las alergias y preferencias necesitan conversarse antes, porque no se garantiza un entorno libre de alérgenos. No se atribuyen premios, estrellas ni relaciones con chefs o restaurantes reales: es una propuesta de demostración académica, sin establecimiento comercial ni fecha de servicio confirmados.','Recoleta, CABA','2 h 30 min',150000,array['En pareja','Con amigos','Interior','Noche']::text[],'plan-mesa-de-autor','Persona terminando el emplatado de un plato de degustación.',array['Menú degustación de cinco pasos','Agua','Bebida sin alcohol']::text[],array['Traslado','Bebidas adicionales']::text[],array['Recepción','Primeros pasos','Platos centrales','Cierre dulce']::text[],'Informá alergias y preferencias alimentarias antes de participar.','Propuesta ficticia sin vínculo con restaurantes, chefs ni distinciones reales. No se garantiza ausencia de alérgenos.',0,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-mesa-de-autor',16,0) on conflict(experiencia_id) do nothing;
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-cocina-de-autor-hecha-por-vos','Cocina de autor, hecha por vos','Interior','Prepará un menú de tres pasos y compartí el resultado.','Preparar un menú completo ayuda a mirar la cocina como un trabajo en equipo. Esta clase ficticia en Palermo organiza un recorrido de tres pasos, desde la planificación y las primeras técnicas hasta el emplatado y la degustación. Los ingredientes y materiales están incluidos para que la atención pueda estar en las tareas y en compartir decisiones. Al final, un recetario permite repasar lo trabajado y guardar ideas para otra ocasión. No es necesario llegar con experiencia, aunque sí seguir las indicaciones y comunicar restricciones alimentarias. La propuesta forma parte de una demostración sin escuela ni chef real asociados; no promete una certificación profesional ni una formación gastronómica acreditada.','Palermo, CABA','3 h 30 min',72000,array['En pareja','Con amigos','Interior','Día','Noche']::text[],'plan-cocina-de-autor-hecha-por-vos','Mesa larga preparada para una experiencia gastronómica.',array['Ingredientes y materiales','Guía','Degustación','Recetario']::text[],array['Traslado','Bebidas adicionales']::text[],array['Organización y técnicas','Preparación en equipo','Emplatado','Degustación y recetario']::text[],'Usá calzado cerrado y pelo recogido. Informá alergias y preferencias alimentarias.','Clase participativa sin conocimientos previos requeridos. La propuesta no implica formación profesional ni certificación.',0,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-cocina-de-autor-hecha-por-vos',12,0) on conflict(experiencia_id) do nothing;
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-cine-para-dos','Cine para dos','Al aire libre','Un rincón al aire libre para compartir una película de a dos.','Un pequeño rincón de jardín alcanza para cambiar una noche de película. Esta propuesta ficticia en San Isidro prepara un espacio para una pareja, con proyección, mantas, pochoclos y una bebida sin alcohol para cada persona. La llegada permite acomodarse antes de empezar la función y disfrutar del entorno sin compartir el sector con un grupo más grande. La reserva es siempre para dos: el valor ilustrativo de cuarenta y ocho mil pesos por persona suma noventa y seis mil en total. No se anuncian títulos concretos ni una programación comercial. Es una experiencia de demostración sin fecha real; al ser exterior, el clima puede hacer necesaria una reprogramación.','San Isidro, Buenos Aires','3 h',48000,array['En pareja','Al aire libre','Noche']::text[],'plan-cine-para-dos','Pantalla de cine y almohadones en un rincón de jardín.',array['Espacio para dos y proyección','Mantas','Pochoclos','Bebida sin alcohol']::text[],array['Traslado','Cena']::text[],array['Recepción de la pareja','Preparación del espacio','Proyección','Cierre']::text[],'Llevá abrigo e informá restricciones alimentarias.','Reserva obligatoria de dos personas: $96.000 en total. Sujeta a reprogramación por clima; no se prometen títulos específicos.',2,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-cine-para-dos',2,0) on conflict(experiencia_id) do nothing;
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-cine-bajo-los-arboles','Cine bajo los árboles','Al aire libre','Una función compartida en un jardín iluminado.','Compartir una película también puede ser una excusa para encontrarse al aire libre. Esta función ficticia en un jardín de Pilar propone asientos tipo puff, una proyección y pochoclos para acomodarse bajo los árboles. La llegada deja tiempo para elegir lugar y conversar antes de que empiece la pantalla, mientras una bebida sin alcohol acompaña la función. Se recomienda llevar abrigo, porque la temperatura puede bajar durante la noche. No se anuncian títulos de películas ni se atribuyen licencias que no estén comprobadas. La propuesta pertenece a una demostración académica sin cine comercial ni fecha reales, y contempla reprogramación cuando el clima no permita utilizar el jardín.','Pilar, Buenos Aires','3 h',24000,array['En pareja','Con amigos','Al aire libre','Noche']::text[],'plan-cine-bajo-los-arboles','Puffs frente a una pantalla de cine bajo árboles y luces.',array['Asiento tipo puff','Proyección','Pochoclos','Bebida sin alcohol']::text[],array['Traslado','Cena']::text[],array['Llegada al jardín','Ubicación y pochoclos','Proyección','Cierre']::text[],'Llevá abrigo y repelente; informá restricciones alimentarias.','Se reprograma con clima adverso. No se prometen películas concretas ni licencias no comprobadas.',0,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-cine-bajo-los-arboles',20,0) on conflict(experiencia_id) do nothing;
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-ceramica-con-tu-sello','Cerámica con tu sello','Interior','Dale forma a una pieza pequeña con tu propia impronta.','La arcilla invita a bajar el ritmo y prestar atención a las manos. Este taller ficticio en Villa Crespo propone modelar y decorar una pieza pequeña, explorando formas y marcas propias con herramientas disponibles y orientación durante el proceso. El encuentro se concentra en la creación, sin exigir conocimientos previos ni un resultado idéntico para todo el grupo. La pieza no está lista para llevar al terminar: necesita un proceso posterior de terminación y un retiro estimado entre quince y veinte días después. Esa espera es parte de trabajar con cerámica. Como propuesta académica, no identifica un taller real ni una fecha de retiro efectiva; tampoco incluye el envío de la pieza.','Villa Crespo, CABA','2 h 30 min',38000,array['En pareja','Con amigos','Interior','Día']::text[],'plan-ceramica-con-tu-sello','Pequeños platos y piezas de cerámica decorados sobre una mesa.',array['Arcilla y herramientas','Guía','Proceso posterior de terminación']::text[],array['Traslado','Envío de la pieza']::text[],array['Ideas y materiales','Modelado','Decoración','Indicaciones de retiro']::text[],'Usá ropa cómoda que pueda mancharse y uñas cortas para trabajar.','Retiro posterior estimado de 15–20 días. La pieza necesita terminación: no se lleva recién cocida al finalizar.',0,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-ceramica-con-tu-sello',12,0) on conflict(experiencia_id) do nothing;
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-ceramica-y-vino','Cerámica y vino','Interior','Modelá, conversá y compartí una degustación sin apuro.','La mesa reúne arcilla, herramientas y conversación en este taller ficticio de Palermo. La propuesta combina el modelado de una pieza con dos degustaciones, dejando tiempo para probar formas y decorar sin apuro. Hay una alternativa sin alcohol para participar del mismo encuentro, y no hace falta tener experiencia previa con cerámica. La guía acompaña el proceso, pero cada persona puede elegir una impronta propia. Al finalizar, la pieza queda para su terminación y se estima un retiro posterior de quince a veinte días: no se entrega cerámica recién cocida al salir. Es una demostración académica sin taller o bodega reales asociados, y el envío no forma parte de lo incluido.','Palermo, CABA','3 h',52000,array['En pareja','Con amigos','Interior','Noche']::text[],'plan-ceramica-y-vino','Piezas de arcilla, herramientas y copas sobre una mesa.',array['Materiales y guía','Terminación de pieza','Dos degustaciones','Opción sin alcohol']::text[],array['Traslado','Envío de la pieza']::text[],array['Bienvenida y materiales','Modelado','Degustación y decoración','Indicaciones de retiro']::text[],'Usá ropa que pueda mancharse e informá restricciones alimentarias.','Alcohol solo para mayores de 18 años; alternativa sin alcohol. Retiro de la pieza estimado de 15–20 días después.',0,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-ceramica-y-vino',12,0) on conflict(experiencia_id) do nothing;
 insert into public.experiencias(id,nombre,categoria,descripcion,detalle,zona,duracion,precio,filtros,imagen,alt,incluye,no_incluye,itinerario,recomendaciones,condiciones,cantidad_fija,estado) values ('plan-a-caballo-entre-paisajes','A caballo entre paisajes','Al aire libre','Un recorrido tranquilo con una pausa para mirar alrededor.','Un recorrido a ritmo tranquilo ofrece otra manera de mirar el paisaje. Esta cabalgata ficticia toma el Valle de Uco como referencia y comienza con la asignación de caballo, el casco y una explicación inicial antes de salir en grupo. El acompañamiento continúa durante el trayecto, que incluye una pausa panorámica y termina con una merienda. Conviene consultar las condiciones personales de participación y preparar pantalón largo y calzado cerrado. La fotografía es ilustrativa: no describe una ruta concreta ni promete cruces de ríos. Tampoco permite asegurar accesibilidad para cualquier situación. La propuesta es académica, sin prestador ni fecha reales, y puede requerir reprogramación según las condiciones meteorológicas.','Valle de Uco, Mendoza','3 h',78000,array['En pareja','Con amigos','Al aire libre','Día']::text[],'plan-a-caballo-entre-paisajes','Caballos con jinetes en un paisaje de montaña y agua, imagen ilustrativa.',array['Asignación de caballo','Casco y explicación inicial','Acompañamiento','Merienda']::text[],array['Traslado','Equipo personal adicional']::text[],array['Asignación e indicaciones','Recorrido tranquilo','Pausa panorámica','Regreso y merienda']::text[],'Usá pantalón largo y calzado cerrado; consultá las condiciones personales de participación.','Se reprograma por clima adverso. La foto es ilustrativa: no se prometen cruces de ríos ni accesibilidad no verificada.',0,'publicado') on conflict(id) do nothing;
 insert into public.cupos_demo(experiencia_id,capacidad,ocupados) values ('plan-a-caballo-entre-paisajes',8,0) on conflict(experiencia_id) do nothing;
 insert into private.catalog_releases(version) values('20261030') on conflict do nothing;
end $seed$;
create or replace function public.crear_pedido_demo(p_experiencia text,p_cantidad integer,p_clave uuid)
returns public.pedidos_demo language plpgsql security definer set search_path='' as $$
declare e public.experiencias; c public.cupos_demo; o public.pedidos_demo;
begin
 if auth.uid() is null then raise insufficient_privilege; end if;
 if p_cantidad is null or p_cantidad not between 1 and 10 or p_clave is null then raise check_violation; end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,0));
 select * into o from public.pedidos_demo where propietario=auth.uid() and clave=p_clave;
 if found then
  if o.experiencia_id<>p_experiencia or o.cantidad<>p_cantidad then raise check_violation; end if;
  return o;
 end if;
 if (select count(*) from public.pedidos_demo where propietario=auth.uid() and created_at > now()-interval '10 minutes') >= 10 then
  raise sqlstate 'PT429' using message='Demasiados pedidos. Esperá unos minutos.';
 end if;
 select * into e from public.experiencias where id=p_experiencia and estado='publicado' for share;
 if not found or e.precio<=0 then raise check_violation; end if;
 if e.cantidad_fija>0 and p_cantidad<>e.cantidad_fija then raise check_violation using message='La experiencia requiere una cantidad fija de personas'; end if;
 select * into c from public.cupos_demo where experiencia_id=e.id for update;
 if not found or c.capacidad-c.ocupados<p_cantidad then raise exception 'Sin cupos' using errcode='P0001'; end if;
 insert into public.pedidos_demo(propietario,experiencia_id,clave,nombre,descripcion,cantidad,precio)
 values(auth.uid(),e.id,p_clave,e.nombre,e.descripcion,p_cantidad,e.precio) returning * into o;
 return o;
end $$;
revoke all on function public.crear_pedido_demo(text,integer,uuid) from public,anon;
grant execute on function public.crear_pedido_demo(text,integer,uuid) to authenticated;
